/**
 * write-tree — write a generated file map to disk, atomically enough to survive a mid-run kill.
 *
 * Strategy: write the whole tree into a sibling `<out>.tmp-<pid>` dir, then `rename` it into place.
 * A SIGKILL before the rename leaves only the temp dir (never a half-written `<out>` reported as
 * success — the chaos-test invariant). On any error we remove the temp dir (clean up our own mess).
 *
 * Containment (T-council BLOCKER): the rename only succeeds onto an empty path, so the destination
 * has to be cleared first. We MUST NOT clear an arbitrary existing directory — that would let
 * `turbo api --out ~/important` delete the user's files with no confirmation. So before clearing,
 * we require the destination to be SAFE to overwrite: it must be absent, empty, or a tree turbo
 * itself generated (every emitted file carries the `Generated by turbo` marker). Anything else is
 * refused with a typed error unless the caller passes `force`.
 */
import { mkdirSync, readdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { err, ok, type Result } from "../core/result.js";

/** The source-comment marker every turbo-emitted `.ts` file carries (templates.ts / emit-service.ts). */
const TURBO_SOURCE_MARKER = "Generated by turbo";

/**
 * Is `dir` safe to overwrite without `force`? Safe = absent, empty, or a previously turbo-generated
 * tree. A directory with foreign files is NOT safe. The primary signal is the self-identifying
 * `_generatedBy:"turbo"` field in the top-level package.json (set by packageJsonSource); the source
 * comment marker on a top-level `.ts` is a fallback.
 */
function overwriteSafety(dir: string): { safe: true } | { safe: false; reason: string } {
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch {
    return { safe: true }; // absent / unreadable-as-dir → the rmSync+mkdir below handles it
  }
  if (entries.length === 0) return { safe: true }; // empty dir is fine to claim

  // Primary: a turbo-generated tree's package.json carries `_generatedBy: "turbo"`.
  try {
    const pkg = JSON.parse(readFileSync(join(dir, "package.json"), "utf8")) as Record<string, unknown>;
    if (pkg._generatedBy === "turbo") return { safe: true };
  } catch {
    // no/unparseable package.json — fall through to the source-marker fallback
  }

  // Fallback: any top-level `.ts` carrying the source comment marker (covers a tree whose
  // package.json predates the `_generatedBy` field).
  const markedSomewhere = entries.some((name) => {
    if (!name.endsWith(".ts")) return false;
    try {
      const full = join(dir, name);
      if (statSync(full).isFile()) return readFileSync(full, "utf8").includes(TURBO_SOURCE_MARKER);
    } catch {
      /* skip unreadable */
    }
    return false;
  });
  if (markedSomewhere) return { safe: true };

  return {
    safe: false,
    reason: `refusing to overwrite non-empty directory not generated by turbo: ${dir} (pass --force to overwrite)`,
  };
}

export function writeTree(
  outDir: string,
  files: Map<string, string>,
  opts: { force?: boolean } = {},
): Result<string, string> {
  const finalDir = resolve(outDir);

  // Containment gate: never delete a directory turbo didn't create unless explicitly forced.
  if (!opts.force) {
    const safety = overwriteSafety(finalDir);
    if (!safety.safe) return err(safety.reason);
  }

  const tmpDir = `${finalDir}.tmp-${process.pid}`;
  try {
    // Clean any stale destination/temp from a prior aborted run. `finalDir` is only removed here
    // AFTER the safety gate above has cleared it (or `force` was passed).
    rmSync(tmpDir, { recursive: true, force: true });
    rmSync(finalDir, { recursive: true, force: true });
    mkdirSync(tmpDir, { recursive: true });

    for (const [rel, contents] of files) {
      const dest = join(tmpDir, rel);
      mkdirSync(dirname(dest), { recursive: true });
      writeFileSync(dest, contents, "utf8");
    }

    // Atomic flip: the tree only "exists" at finalDir once fully written.
    renameSync(tmpDir, finalDir);
    return ok(finalDir);
  } catch (e) {
    // Clean up the partial temp dir — never leave a half-tree masquerading as output.
    try {
      rmSync(tmpDir, { recursive: true, force: true });
    } catch (cleanupErr) {
      console.warn(
        "[write-tree] temp cleanup failed:",
        cleanupErr instanceof Error ? cleanupErr.message : String(cleanupErr),
      );
    }
    return err(`write failed: ${e instanceof Error ? e.message : String(e)}`);
  }
}
